sp_widget.css:
/*
===============================================================================
MANAGER DASHBOARD — SPAR Futuristic edition
Paste into the widget's CSS field
Same move as the other widgets: dark cyan/teal panel look → light glass cards,
red-to-green gradient accents, animated stat cards and bars.
HTML/ng-repeat structure is untouched — only the CSS below needs to change.
===============================================================================
*/

/* Dashboard Container */
.manager-dashboard {
  padding: 24px;
  font-family: 'Inter', 'Segoe UI', sans-serif;
}

/* Header */
.dashboard-header {
  margin-bottom: 32px;
}
.dashboard-title {
  font-size: 2rem;
  font-weight: 800;
  color: #0F172A;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}
.dashboard-subtitle {
  font-size: 0.875rem;
  color: #64748B;
}

/* Stats Row */
.stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 32px;
}

.stat-card {
  position: relative;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid #E2E8F0;
  border-radius: 14px;
  padding: 24px;
  text-align: center;
  transition: transform 280ms cubic-bezier(0.34, 1.56, 0.64, 1),
              box-shadow 280ms ease,
              border-color 280ms ease;
  animation: statFadeInUp 450ms cubic-bezier(0.16,1,0.3,1) both;
}
.stats-row .stat-card:nth-child(2) { animation-delay: 60ms; }
.stats-row .stat-card:nth-child(3) { animation-delay: 120ms; }
.stats-row .stat-card:nth-child(4) { animation-delay: 180ms; }

.stat-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, $brand-primary 0%, $brand-success 100%);
  opacity: 0;
  transition: opacity 280ms ease;
}
.stat-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 14px 28px -6px rgba(15, 23, 42, 0.14);
  border-color: #CBD5E1;
}
.stat-card:hover::before {
  opacity: 1;
}

/* Default stat value — bold gradient text, ties every number back to the brand */
.stat-value {
  font-size: 2.5rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 8px;
  background: linear-gradient(135deg, $brand-primary 0%, $brand-success 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.stat-label {
  font-size: 0.8rem;
  font-weight: 700;
  color: #64748B;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Overdue variant */
.stat-card.overdue {
  border-color: rgba(227, 6, 19, 0.20);
  background: rgba(227, 6, 19, 0.04);
}
.stat-card.overdue:hover {
  box-shadow: 0 14px 28px -6px rgba(227, 6, 19, 0.22);
}
.stat-card.overdue .stat-value {
  background: none;
  -webkit-background-clip: unset;
  background-clip: unset;
  color: $brand-danger;
  animation: overduePulseText 2.4s ease-in-out infinite;
}
@keyframes overduePulseText {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.65; }
}

/* Success variant */
.stat-card.success {
  border-color: rgba(0, 122, 51, 0.20);
  background: rgba(0, 122, 51, 0.04);
}
.stat-card.success:hover {
  box-shadow: 0 14px 28px -6px rgba(0, 122, 51, 0.22);
}
.stat-card.success .stat-value {
  background: none;
  -webkit-background-clip: unset;
  background-clip: unset;
  color: $brand-success;
}

/* Sections */
.section {
  position: relative;
  margin-bottom: 32px;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid #E2E8F0;
  border-radius: 14px;
  padding: 24px;
  overflow: hidden;
  transition: box-shadow 280ms ease;
}
.section::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, $brand-primary 0%, $brand-success 100%);
  opacity: 0.85;
}
.section:hover {
  box-shadow: 0 10px 24px -6px rgba(15, 23, 42, 0.10);
}
.section-title {
  position: relative;
  display: inline-block;
  padding-left: 14px;
  font-size: 0.75rem;
  font-weight: 800;
  color: $brand-primary;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  margin-bottom: 20px;
}
.section-title::before {
  content: "";
  position: absolute;
  left: 0;
  top: 2px;
  bottom: 2px;
  width: 4px;
  border-radius: 999px;
  background: linear-gradient(180deg, $brand-primary, $brand-success);
}

/* Category Breakdown */
.category-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.category-item {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.category-info {
  display: flex;
  justify-content: space-between;
}
.category-name {
  font-size: 0.875rem;
  font-weight: 600;
  color: #0F172A;
}
.category-count {
  font-size: 0.875rem;
  font-weight: 700;
  color: $brand-success;
}
.category-bar-container {
  width: 100%;
  height: 9px;
  background: #F1F5F9;
  border: 1px solid #E2E8F0;
  border-radius: 999px;
  overflow: hidden;
}
.category-bar-fill {
  position: relative;
  height: 100%;
  background: linear-gradient(135deg, $brand-primary 0%, $brand-success 100%);
  border-radius: 999px;
  overflow: hidden;
  transition: width 0.7s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.category-bar-fill::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.5) 50%, rgba(255,255,255,0) 100%);
  transform: translateX(-100%);
  animation: barShimmer 2.4s ease-in-out infinite;
}
@keyframes barShimmer {
  to { transform: translateX(100%); }
}

/* Overdue Items */
.overdue-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.overdue-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px;
  background: rgba(227, 6, 19, 0.04);
  border: 1px solid rgba(227, 6, 19, 0.18);
  border-radius: 10px;
  transition: transform 250ms cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 250ms ease, border-color 250ms ease;
}
.overdue-item:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 18px -4px rgba(227, 6, 19, 0.20);
  border-color: rgba(227, 6, 19, 0.35);
}
.overdue-number {
  font-size: 0.75rem;
  font-weight: 700;
  color: $brand-success;
  margin-bottom: 4px;
}
.overdue-desc {
  font-size: 0.875rem;
  color: #0F172A;
}
.overdue-meta {
  text-align: right;
}
.overdue-badge {
  display: inline-block;
  background: rgba(227, 6, 19, 0.12);
  color: $brand-danger;
  border: 1px solid rgba(227, 6, 19, 0.30);
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 10px;
  margin-bottom: 4px;
  animation: badgePulse 2.2s ease-in-out infinite;
}
@keyframes badgePulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(227, 6, 19, 0.25); }
  50%      { box-shadow: 0 0 0 5px rgba(227, 6, 19, 0); }
}
.overdue-assignee {
  font-size: 0.75rem;
  color: #94A3B8;
}

/* Empty State */
.empty-state {
  text-align: center;
  padding: 24px;
  color: $brand-success;
  font-size: 0.9rem;
  font-weight: 600;
}
/* =============================================================================
   ACCESS DENIED
   ============================================================================= */

.access-denied {
  text-align: center;
  padding: 80px 32px;
  background: rgba(227, 6, 19, 0.03);
  border: 1px solid rgba(227, 6, 19, 0.15);
  border-radius: 14px;
  margin: 24px 0;
  animation: statFadeInUp 450ms cubic-bezier(0.16,1,0.3,1) both;
}

.access-denied-icon {
  font-size: 4rem;
  margin-bottom: 16px;
}

.access-denied-title {
  font-size: 1.8rem !important;
  font-weight: 800 !important;
  color: #0F172A !important;
  letter-spacing: -0.02em !important;
  margin-bottom: 12px !important;
}

.access-denied-msg {
  font-size: 1rem !important;
  color: #334155 !important;
  margin-bottom: 8px !important;
  max-width: 480px;
  margin-left: auto;
  margin-right: auto;
}

.access-denied-sub {
  font-size: 0.875rem !important;
  color: #64748B !important;
  margin-bottom: 32px !important;
}

.access-denied-sub strong {
  color: $brand-primary;
  font-weight: 700;
}

.access-denied-btn {
  display: inline-block;
  background: linear-gradient(135deg, $brand-primary 0%, $brand-success 100%);
  color: #FFFFFF !important;
  font-weight: 700;
  font-size: 0.9rem;
  padding: 12px 32px;
  border-radius: 999px;
  text-decoration: none !important;
  transition: all 0.22s ease;
  box-shadow: 0 4px 16px rgba(0, 122, 51, 0.20);
}

.access-denied-btn:hover {
  opacity: 0.88;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 122, 51, 0.30);
  color: #FFFFFF !important;
}
/* Access Denied Buttons */
.access-denied-actions {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.access-denied-btn.primary {
  background: linear-gradient(135deg, $brand-primary 0%, $brand-success 100%);
  color: #FFFFFF !important;
  box-shadow: 0 4px 16px rgba(0, 122, 51, 0.20);
}

.access-denied-btn.primary:hover {
  opacity: 0.88;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 122, 51, 0.30);
  color: #FFFFFF !important;
}

.access-denied-btn.secondary {
  background: transparent !important;
  color: #334155 !important;
  border: 1px solid #CBD5E1;
  box-shadow: none !important;
}

.access-denied-btn.secondary:hover {
  background: #F8FAFC !important;
  border-color: #94A3B8;
  transform: translateY(-2px);
  color: #0F172A !important;
}

/* Entrance animation */
@keyframes statFadeInUp {
  from { opacity: 0; transform: translateY(14px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* Responsive */
@media (max-width: 900px) {
  .stats-row {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 560px) {
  .stats-row {
    grid-template-columns: 1fr;
  }
  .overdue-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
  }
  .overdue-meta {
    text-align: left;
  }
}

sp_widget.script:
(function() {
    // Check if user has manager role OR is in IT Manager group
    var hasRole = gs.hasRole('x_2062828_it_onb_0.manager');

    var inGroup = false;
    var groupGr = new GlideRecord('sys_user_grmember');
    groupGr.addQuery('user', gs.getUserID());
    groupGr.addQuery('group.name', 'IT Manager');
    groupGr.query();
    if (groupGr.next()) {
        inGroup = true;
    }

    data.hasAccess = hasRole || inGroup;

    // Stop here if no access
    if (!data.hasAccess) return;

    var now = new GlideDateTime();
    var thirtyDaysAgo = new GlideDateTime();
    thirtyDaysAgo.addDaysUTC(-30);

    // Total requests in last 30 days
    var totalGr = new GlideRecord('sc_req_item');
    totalGr.addQuery('sys_created_on', '>=', thirtyDaysAgo);
    totalGr.query();
    data.totalRequests = totalGr.getRowCount();

    // Resolved count
    var resolvedGr = new GlideRecord('sc_req_item');
    resolvedGr.addQuery('sys_created_on', '>=', thirtyDaysAgo);
    resolvedGr.addQuery('state', '3');
    resolvedGr.query();
    data.resolvedCount = resolvedGr.getRowCount();

    // Average resolution time
    var avgGr = new GlideRecord('sc_req_item');
    avgGr.addQuery('sys_created_on', '>=', thirtyDaysAgo);
    avgGr.addQuery('state', '3');
    avgGr.query();

    var totalDays = 0;
    var resolvedItems = 0;
    while (avgGr.next()) {
        if (avgGr.getValue('closed_at') && avgGr.getValue('sys_created_on')) {
            var created = new GlideDateTime(avgGr.getValue('sys_created_on'));
            var closed = new GlideDateTime(avgGr.getValue('closed_at'));
            var diff = GlideDateTime.subtract(created, closed);
            totalDays += Math.round(diff.getRoundedDayPart());
            resolvedItems++;
        }
    }
    data.avgResolutionTime = resolvedItems > 0 ? 
        Math.round(totalDays / resolvedItems) : 0;

    // Overdue requests
    var overdueItems = [];
    var overdueGr = new GlideRecord('sc_req_item');
    overdueGr.addQuery('sys_created_on', '>=', thirtyDaysAgo);
    overdueGr.addQuery('due_date', '<', now);
    overdueGr.addQuery('state', 'NOT IN', '3,4,7');
    overdueGr.query();

    data.overdueCount = overdueGr.getRowCount();

    overdueGr = new GlideRecord('sc_req_item');
    overdueGr.addQuery('sys_created_on', '>=', thirtyDaysAgo);
    overdueGr.addQuery('due_date', '<', now);
    overdueGr.addQuery('state', 'NOT IN', '3,4,7');
    overdueGr.setLimit(10);
    overdueGr.query();

    while (overdueGr.next()) {
        var dueDate = new GlideDateTime(overdueGr.getValue('due_date'));
        var diff = GlideDateTime.subtract(dueDate, now);
        var daysOverdue = Math.abs(Math.round(diff.getRoundedDayPart()));

        overdueItems.push({
            number: overdueGr.getValue('number'),
            short_description: overdueGr.getValue('short_description'),
            assigned_to: overdueGr.getDisplayValue('assigned_to'),
            days_overdue: daysOverdue
        });
    }
    data.overdueItems = overdueItems;

    // Category breakdown
    var categories = {};
    var catGr = new GlideRecord('sc_req_item');
    catGr.addQuery('sys_created_on', '>=', thirtyDaysAgo);
    catGr.query();

    while (catGr.next()) {
        var itemName = catGr.getDisplayValue('cat_item') || 'General';
        var category = 'General';

        if (itemName.indexOf('Equipment') > -1) category = 'Equipment';
        else if (itemName.indexOf('Access') > -1 || 
                 itemName.indexOf('Permission') > -1) category = 'System Access';
        else if (itemName.indexOf('Workplace') > -1) category = 'Workplace';
        else if (itemName.indexOf('Support') > -1) category = 'IT Support';

        categories[category] = (categories[category] || 0) + 1;
    }

    var categoryList = [];
    for (var cat in categories) {
        categoryList.push({ name: cat, count: categories[cat] });
    }
    categoryList.sort(function(a, b) { return b.count - a.count; });
    data.categories = categoryList;

})();
